[entities]
;; The Chozo statue in the chamber (32x32, by its top-left tile).
deco 6 41 kind=chozo
;; Zoomers circle free platforms (shaft 1's at row 28, shaft 2's at row 16), starting on top.
zoomer 39 27 dir=-1
zoomer 7 15 dir=1
;; Rippers fly wall to wall at one height (by the row their body is in).
ripper 40 32 dir=1
ripper 36 23 dir=-1
ripper 6 14 dir=1
;; Skrees hang under the ceilings (by the tile just below the ceiling).
skree 18 37
skree 34 16
skree 20 16
skree 7 1
skree 30 1
;; The ship (64x32) on the hangar floor: by its left tile and the row its feet stand in.
ship 41 10
;; Alarm lights on the back wall.
deco 2 35 kind=alarm
deco 13 35 kind=alarm
